import { cn } from '../../../lib/utils';

export type AgentBlockProps = {
  /**
   * Who produced this and what state it is in — "Generated by AI",
   * "AI · Awaiting review". **Required.** The authorship signal is the product's
   * trust story; an unlabelled agent block is the failure this component
   * exists to prevent.
   */
  authorship: string;
  children: React.ReactNode;
  /** Accept / reject / edit controls. Rendered in the header, trailing. */
  actions?: React.ReactNode;
  /** Timestamp or model reference, beside the authorship label. */
  meta?: React.ReactNode;
  className?: string;
};

/**
 * AgentBlock — product. **A category of one, on purpose.**
 *
 * Agent-authored content is a distinct class with its own constraints, and
 * `CLAUDE.md` is explicit: do not build agent output as a generic card. The
 * authorship signal is the product's trust story and it disappears silently
 * the moment someone reaches for the wrong primitive.
 *
 * §5 specifies the treatment, and both signals are mandatory together:
 *
 *   1. a 2px left rail in solid `--color-text-agent`
 *   2. an explicit text label, in `--color-text-agent`
 *
 * The block itself is neutral: a 1px `--color-border` box on the ground it
 * sits on. Decided 2026-10-14, when the violet ground and the robot icon
 * went: in the emerald-accented UI a violet field read as decoration, not as
 * a signal. The rail and the written label still say "agent" on their own,
 * so authorship survives grayscale, deuteranopia and a printed page — §5's
 * own requirement.
 *
 * **Orchid marks authorship and agent activity only** (§1). It never means
 * "good", "new" or "important". If orchid starts appearing on things the agent
 * did not produce, the system has failed.
 */
function AgentBlock({ authorship, children, actions, meta, className }: AgentBlockProps) {
  return (
    <div
      data-slot="agent-block"
      className={cn(
        // Neutral box, no ground: orchid is the rail and the label only (§5).
        'rounded-md border border-border',
        // §7.8 — 2px is reserved for exactly three things, and the agent rail
        // is one of them. It is what makes authorship legible at a glance.
        // Solid --color-text-agent, not the --color-border-agent tint: with
        // no violet ground behind it the tint measured 1.3:1, under the 3:1 a
        // required graphical signal needs (WCAG 1.4.11). Solid it is 6.17:1 or
        // more on the canvas, surface and raised step, both modes (§4).
        'border-l-[length:var(--border-width-2)] border-l-text-agent',
        className,
      )}
    >
      <div className="flex items-center gap-[var(--gap-control-icon)] px-[var(--pad-card)] pt-[var(--pad-card)]">
        <span className="text-2xs font-medium uppercase tracking-[var(--tracking-wide)] text-text-agent">
          {authorship}
        </span>
        {meta ? <span className="text-xs text-text-secondary">{meta}</span> : null}
        {actions ? <div className="ml-auto flex items-center gap-[var(--gap-inline)]">{actions}</div> : null}
      </div>

      <div className="p-[var(--pad-card)] text-base text-text-body">{children}</div>
    </div>
  );
}

export { AgentBlock };
